-- hejmo:foreign-keys-off
-- Religious holidays calendar (ticket 339): a calendar generated by the box
-- from the religions a household chooses, kind 'religious'. SQLite cannot
-- change a CHECK constraint, so the table is rebuilt (the marker above runs
-- this migration with foreign keys off, so the drop does not cascade into events).
CREATE TABLE calendars_new (
    id            TEXT PRIMARY KEY,
    household_id  TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE,
    name          TEXT NOT NULL,
    kind          TEXT NOT NULL CHECK (kind IN ('local', 'ics', 'caldav', 'google', 'meals', 'outlook', 'birthdays', 'religious')),
    color         TEXT NOT NULL DEFAULT '',
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    connection_id TEXT REFERENCES calendar_connections(id) ON DELETE CASCADE,
    read_only     INTEGER NOT NULL DEFAULT 0,
    shared        INTEGER NOT NULL DEFAULT 0,
    remote_url    TEXT,
    waste         INTEGER NOT NULL DEFAULT 0,
    source_locked INTEGER NOT NULL DEFAULT 0,
    source_owner  TEXT NOT NULL DEFAULT '',
    source_name   TEXT NOT NULL DEFAULT ''
);
INSERT INTO calendars_new (rowid, id, household_id, name, kind, color, created_at, updated_at, connection_id, read_only, shared, remote_url, waste, source_locked, source_owner, source_name)
    SELECT rowid, id, household_id, name, kind, color, created_at, updated_at, connection_id, read_only, shared, remote_url, waste, source_locked, source_owner, source_name FROM calendars;
DROP TABLE calendars;
ALTER TABLE calendars_new RENAME TO calendars;
CREATE UNIQUE INDEX calendars_remote_url ON calendars (connection_id, remote_url) WHERE remote_url IS NOT NULL;

-- Off by default: Hejmo never guesses a faith. religious_holidays is the set of
-- religions (comma-separated codes, alphabetical), kept while the switch is off.
-- The two calendar choices default to the Diyanet table and the revised Julian
-- calendar (Christmas on 25 December); the latter is shared with the calendar
-- style of ticket 338. The language names the events and the calendar.
ALTER TABLE households ADD COLUMN religious_holidays_on INTEGER NOT NULL DEFAULT 0;
ALTER TABLE households ADD COLUMN religious_holidays TEXT NOT NULL DEFAULT '';
ALTER TABLE households ADD COLUMN islamic_calendar TEXT NOT NULL DEFAULT 'diyanet' CHECK (islamic_calendar IN ('diyanet', 'umm_al_qura'));
ALTER TABLE households ADD COLUMN orthodox_calendar TEXT NOT NULL DEFAULT 'revised_julian' CHECK (orthodox_calendar IN ('revised_julian', 'julian'));
ALTER TABLE households ADD COLUMN religious_holidays_lang TEXT NOT NULL DEFAULT 'de';

-- An event of the generated calendar says which holiday it is made from (the
-- event page recomputes the details), whether it is the extra event of the
-- evening before ("<Fest> beginnt am Abend") and whether the day depends on
-- moon sighting ("oder 1 Tag später").
ALTER TABLE events ADD COLUMN religious TEXT;
ALTER TABLE events ADD COLUMN religious_key TEXT;
ALTER TABLE events ADD COLUMN religious_eve INTEGER NOT NULL DEFAULT 0;
ALTER TABLE events ADD COLUMN religious_vary INTEGER NOT NULL DEFAULT 0;
CREATE INDEX events_religious ON events (calendar_id) WHERE religious IS NOT NULL;
